import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Boss } from '../Entity/Boss';
import type { Turret } from '../Entity/Turret';
import type { TurretScheduleState } from '../Entity/TurretSchedule';

/**
 * 编排：决定当前哪个炮台有开火权，写到 turret.active。
 * 不碰瞄准、不碰开火。
 */
export class TurretScheduleSystem implements System {

    onTick(world: World, dt: number): void {
        for (const boss of world.query<Boss>('boss')) {
            if (!boss.alive || boss.hp <= 0) continue;
            this._tickSchedule(world, boss, dt);
        }
    }

    private _tickSchedule(world: World, boss: Boss, dt: number): void {
        const turrets = this._collectTurrets(world, boss);
        const schedule = boss.turretSchedule;

        // 无 schedule 或 volley：所有炮台 active
        if (!schedule || schedule.config.mode === 'volley') {
            for (const t of turrets) t.active = true;
            return;
        }

        // sequence 模式
        this._tickSequence(boss, schedule, turrets, dt);
    }

    private _collectTurrets(world: World, boss: Boss): Turret[] {
        const result: Turret[] = [];
        for (const t of world.query<Turret>('turret')) {
            if (t.ownerId === boss.id && t.alive && t.hp > 0) result.push(t);
        }
        return result;
    }

    private _tickSequence(
        boss: Boss,
        s: TurretScheduleState,
        turrets: Turret[],
        dt: number,
    ): void {
        // 先全部清零
        for (const t of turrets) t.active = false;

        // 已结束
        if (s.activeIndex < 0) return;

        // 喘息中
        if (s.gapTimer > 0) {
            s.gapTimer -= dt;
            if (s.gapTimer <= 0) {
                s.gapTimer = 0;
                s.burstElapsed = 0;
            }
            return;
        }

        // 当前 active 的炮台
        const turret = turrets[s.activeIndex];
        if (!turret) {
            // 索引越界（存活炮台数变少），重置回 0
            s.activeIndex = 0;
            s.burstElapsed = 0;
            return;
        }
        turret.active = true;

        // 累积持续时间
        s.burstElapsed += dt;
        const burstDuration = s.config.burstDuration ?? 2;
        if (s.burstElapsed >= burstDuration) {
            this._advanceTurret(turrets, s);
        }
    }

    private _advanceTurret(turrets: Turret[], s: TurretScheduleState): void {
        s.activeIndex++;

        if (s.activeIndex >= turrets.length) {
            if (s.config.loop ?? true) {
                s.activeIndex = 0;
            } else {
                s.activeIndex = -1;
                s.burstElapsed = 0;
                s.gapTimer = 0;
                return;
            }
        }

        const next = turrets[s.activeIndex];
        if (next) next.cooldownTimer = 0;

        s.gapTimer = s.config.burstGap ?? 1;
        s.burstElapsed = 0;
    }
}